// campaign.js — FREEMON campaign data: 10 acts x 10 levels = 100 levels, generated by code but fully deterministic.
// Pure data + tiny helpers (no DOM, no storage, no three.js), so Node tests, the runner and the menus can all import it.
//
//   LEVELS[i] = {
//     id: 1..100, act: 1..10, idx: 1..10, name: 'İlk Kar', biome: 'snow', seed: uint32,
//     length: metres (500 at L1 -> 2600 at L100, with an in-act ramp), hardness: 0.7..1.8, startTier: 0..4,
//     features: ['waves', ...]            // every set-piece / mechanic allowed on this level (cumulative)
//     intro: { text, icon, feature } | null   // level that introduces something new -> show a tutorial card
//     goals: [ {star:1, kind:'finish', text},
//              {star:2, kind:'flakes', pct, text} | {star:2, kind:'flakesN', n, text},
//              {star:3, kind:'noloss'|'nocrash'|'maxsize'|'yeti'|'perfects'|'powerups', ...params, text} ],
//     boss: bool                          // idx 10: Yeti boss level (faster Yeti, throws boulders)
//   }
//
// Goal evaluation uses a stats object the runner fills at the end of a level (see evalGoals).

export const CAMPAIGN_SIZE = 100;
export const LEVELS_PER_ACT = 10;

