const lerp = (a, b, t) => a + (b - a) * t;
const round5 = (x) => Math.round(x / 5) * 5;

function seedFor(id) {
  let h = Math.imul(id, 0x9e3779b1) ^ 0x85ebca6b;
  h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d);
  h = Math.imul(h ^ (h >>> 12), 0x297a2d39);
  return ((h ^ (h >>> 15)) >>> 0) || 1;
}

function star3Goal(id, idx, boss, act, length, startTier, t) {
  if (boss) {
    return act % 2 === 1
      ? { star: 3, kind: 'yeti', gap: 12, text: "Yeti 12 m'den fazla yaklaşmasın" }
      : { star: 3, kind: 'noloss', text: 'Hiç boyut kaybetme' };
  }
  const pool = ['noloss'];
  if (id >= 2) pool.push('nocrash');
  if (id >= 3) pool.push('yeti');
  if (id >= 5) pool.push('perfects');
  if (id >= 7) pool.push('powerups');
  if (length >= 1400 || startTier >= 2) pool.push('maxsize');
  const kind = id <= 3 ? 'noloss' : pool[(id * 3 + act) % pool.length];
  switch (kind) {
    case 'nocrash': return { star: 3, kind, text: 'Hiç çarpmadan bitir' };
    case 'maxsize': return { star: 3, kind, text: 'Maksimum boyutla bitir' };
    case 'yeti': return { star: 3, kind, gap: 10, text: "Yeti 10 m'den fazla yaklaşmasın" };
    case 'perfects': { const n = 3 + Math.round(t * 12); return { star: 3, kind, n, text: `${n} kez PERFECT yap` }; }
    case 'powerups': { const n = 2 + Math.round(t * 4); return { star: 3, kind, n, text: `${n} güçlendirme topla` }; }
    default: return { star: 3, kind: 'noloss', text: 'Hiç boyut kaybetme' };
  }
}

function build() {
  const out = [];
  for (let id = 1; id <= CAMPAIGN_SIZE; id++) {
    const act = Math.ceil(id / LEVELS_PER_ACT);
    const idx = ((id - 1) % LEVELS_PER_ACT) + 1;
    const boss = idx === LEVELS_PER_ACT;
    const t = (id - 1) / (CAMPAIGN_SIZE - 1);
    const u = (idx - 1) / (LEVELS_PER_ACT - 1);

    // in-act ramp: each act starts a little easier/shorter than it ends; endpoints land exactly on 500 and 2600
    const length = Math.round((lerp(532, 2500, t) * (0.94 + 0.1 * u)) / 10) * 10;
    const hardness = Math.round(Math.max(0.7, Math.min(1.8, lerp(0.7, 1.8, t) + 0.06 * (u - 0.5) + (boss ? 0.05 : 0))) * 100) / 100;
    const startTier = id <= 20 ? 1 : act >= 3 && idx === 7 ? 2 : 0;

    const features = FEATURE_ORDER.filter((f) => FEATURE_INTRO[f] <= id);
    const intro = INTROS[id] ? { ...INTROS[id] } : null;

    const pct = Math.max(40, Math.min(90, round5(40 + 45 * t + (idx % 3 === 0 ? 5 : 0))));
    const goal2 = idx % 4 === 0 && !boss
      ? (() => { const n = Math.max(10, round5((length / 8) * (pct / 100))); return { star: 2, kind: 'flakesN', n, text: `${n} kar tanesi topla` }; })()
      : { star: 2, kind: 'flakes', pct: pct / 100, text: `Kar tanelerinin %${pct}'ini topla` };

    out.push({
      id, act, idx, name: NAMES[act - 1][idx - 1], biome: ACTS[act - 1].biome, seed: seedFor(id),
      length, hardness, startTier, features, intro,
      goals: [{ star: 1, kind: 'finish', text: 'Bölümü bitir' }, goal2, star3Goal(id, idx, boss, act, length, startTier, t)],
      boss,
    });
  }
  return out;
}

export const LEVELS = build();

export const levelById = (id) => LEVELS[(Math.floor(Number(id)) || 0) - 1] || null;
export const actOf = (idOrLevel) => {
  const id = typeof idOrLevel === 'object' && idOrLevel ? idOrLevel.id : idOrLevel;
  return ACTS[Math.ceil((Number(id) || 1) / LEVELS_PER_ACT) - 1] || ACTS[0];
};
export const levelsOfAct = (act) => LEVELS.slice((act - 1) * LEVELS_PER_ACT, act * LEVELS_PER_ACT);

// stats the runner fills at the end of a campaign level (all optional except what the level's goals need):
//   { finished=true, flakes, flakesPct /*0..1 of the level's snowflakes*/, crashes, layersLost, maxTier, minYetiGap /*m*/, perfects, powerups, time }
// Returns [bool, bool, bool]. A level that was not finished earns nothing.
export function evalGoals(level, stats = {}) {
  const lv = typeof level === 'number' ? levelById(level) : level;
  if (!lv) return [false, false, false];
  const s = stats || {};
  const num = (x, d = 0) => (typeof x === 'number' && Number.isFinite(x) ? x : d);
  if (s.finished === false) return [false, false, false];
  return lv.goals.map((g) => {
    switch (g.kind) {
      case 'finish': return true;
      case 'flakes': return num(s.flakesPct) >= g.pct - 1e-9;
      case 'flakesN': return num(s.flakes) >= g.n;
      case 'noloss': return num(s.layersLost, 0) === 0;
      case 'nocrash': return num(s.crashes, 0) === 0;
      case 'maxsize': return num(s.maxTier) >= 4;
      case 'yeti': return num(s.minYetiGap, Infinity) >= g.gap;
      case 'perfects': return num(s.perfects) >= g.n;
      case 'powerups': return num(s.powerups) >= g.n;
      default: return false;
    }
  });
}
export const countStars = (met) => (Array.isArray(met) ? met.filter(Boolean).length : 0);
